property.value:
let $proxyNames := (
      'org.springframework.transaction.annotation.Transactional',
      'org.springframework.scheduling.annotation.Async',
      'org.springframework.cache.annotation.Cacheable',
      'org.springframework.cache.annotation.CachePut',
      'org.springframework.cache.annotation.CacheEvict',
      'org.springframework.cache.annotation.Caching',
      'org.springframework.retry.annotation.Retryable',
      'org.springframework.retry.annotation.CircuitBreaker',
      'org.springframework.resilience.annotation.Retryable',
      'org.springframework.resilience.annotation.ConcurrencyLimit',
      'org.springframework.security.access.prepost.PreAuthorize',
      'org.springframework.security.access.prepost.PostAuthorize',
      'org.springframework.security.access.prepost.PreFilter',
      'org.springframework.security.access.prepost.PostFilter',
      'org.springframework.security.access.annotation.Secured',
      'jakarta.annotation.security.RolesAllowed',
      'javax.annotation.security.RolesAllowed',
      'jakarta.annotation.security.DenyAll',
      'javax.annotation.security.DenyAll',
      'io.github.resilience4j.retry.annotation.Retry',
      'io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker',
      'io.github.resilience4j.ratelimiter.annotation.RateLimiter',
      'io.github.resilience4j.bulkhead.annotation.Bulkhead',
      'io.github.resilience4j.timelimiter.annotation.TimeLimiter',
      'io.micrometer.core.annotation.Timed',
      'io.micrometer.core.annotation.Counted',
      'io.micrometer.observation.annotation.Observed',
      $projectProxyAnnotations),
    $constraintNames := (
      for $name in (
        'AssertFalse', 'AssertTrue', 'DecimalMax', 'DecimalMin', 'Digits', 'Email', 'Future',
        'FutureOrPresent', 'Max', 'Min', 'Negative', 'NegativeOrZero', 'NotBlank', 'NotEmpty',
        'NotNull', 'Null', 'Past', 'PastOrPresent', 'Pattern', 'Positive', 'PositiveOrZero', 'Size')
      return ('jakarta.validation.constraints.' || $name, 'javax.validation.constraints.' || $name),
      for $name in (
        'CodePointLength', 'CreditCardNumber', 'Currency', 'EAN', 'ISBN', 'Length', 'LuhnCheck',
        'Mod10Check', 'Mod11Check', 'Normalized', 'Range', 'URL', 'UUID', 'UniqueElements')
      return 'org.hibernate.validator.constraints.' || $name,
      'jakarta.validation.Valid', 'javax.validation.Valid', $projectConstraintAnnotations),
    $proxyAnnotation := function($annotation) {
      exists($annotation[some $name in $proxyNames satisfies pmd-java:typeIs($name)])
    },
    $typeOf := function($node) {
      $node/ancestor::*[self::ClassDeclaration or self::AnonymousClassDeclaration
        or self::EnumDeclaration or self::RecordDeclaration][1]
    },
    $validated := function($method) {
      exists($typeOf($method)/self::ClassDeclaration/ModifierList/Annotation[
        pmd-java:typeIs('org.springframework.validation.annotation.Validated')])
      and exists($method[not(@Visibility = 'private' or pmd-java:modifiers() = 'static')])
      and exists(($method[not(@Arity = 0 and matches(@Name, '^(get|is)\p{Lu}'))]/ModifierList/Annotation
                  | $method/FormalParameters//Annotation)[
        some $name in $constraintNames satisfies pmd-java:typeIs($name)])
    },
    $transactionType := 'org.springframework.transaction.annotation.Transactional',
    $joiningPropagation := ('REQUIRED', 'SUPPORTS', 'MANDATORY'),
    $matchedAttributes := ('rollbackFor', 'rollbackForClassName', 'noRollbackFor', 'noRollbackForClassName',
      'timeout', 'timeoutString', 'isolation', 'value', 'transactionManager'),
    $running := function($annotation) {
      empty($annotation/AnnotationMemberList/MemberValuePair[@Name = 'propagation']
        [not(*[1][@Name = ('REQUIRED', 'REQUIRES_NEW', 'MANDATORY', 'NESTED')])])
    },
    $signature := function($pair) {
      string-join(for $node in $pair/descendant-or-self::*
        return string-join((name($node), $node/@Name, $node/@SimpleName, $node/@Image), ':'), '|')
    },
    $joins := function($annotation, $callerAnnotations) {
      exists($callerAnnotations)
      and exists($annotation[pmd-java:typeIs($transactionType)])
      and (every $pair in $annotation/AnnotationMemberList/MemberValuePair satisfies
        ($pair/@Name = 'readOnly' or $pair/@Name = 'label'
         or ($pair/@Name = 'propagation' and exists($pair/*[1][@Name = $joiningPropagation]))
         or ($pair/@Name = $matchedAttributes
             and (some $same in $callerAnnotations/AnnotationMemberList/MemberValuePair[@Name = $pair/@Name]
                  satisfies $signature($same) = $signature($pair)))))
    },
    $proxied := function($method, $callerAnnotations) {
      exists($method/ModifierList/Annotation[$proxyAnnotation(.)][not($joins(., $callerAnnotations))])
      or $validated($method)
    },
    $transactional := function($node) {
      let $caller := $node/ancestor::MethodDeclaration[1],
          $own := $caller/ModifierList/Annotation[pmd-java:typeIs($transactionType)]
      return ($own[$running(.)],
        $caller[empty($own)][not(@Visibility = 'private' or pmd-java:modifiers() = 'static')]
          /ancestor::ClassDeclaration[1]/ModifierList/Annotation[pmd-java:typeIs($transactionType)][$running(.)])
    }
return (
  //MethodCall[*[1][self::ArgumentList or self::TypeArguments or self::ThisExpression[not(*)]]][
    let $name := @MethodName,
        $arity := count(ArgumentList/*),
        $callerAnnotations := $transactional(.)
    return exists($typeOf(.)/self::ClassDeclaration/ClassBody/MethodDeclaration[@Name = $name]
      [@Arity = $arity or (@Varargs and $arity >= @Arity - 1)]
      [$proxied(., $callerAnnotations)])
  ]
  |
  //MethodReference[*[1][self::ThisExpression[not(*)]]][
    let $name := @MethodName,
        $callerAnnotations := $transactional(.)
    return exists($typeOf(.)/self::ClassDeclaration/ClassBody/MethodDeclaration[@Name = $name]
      [$proxied(., $callerAnnotations)])
  ]
)
